function (params) {
            $('#covgLIFiveYrSelf_selBenefitAmt')[0].selectize.disable();
            $('.spouse-applying-life').hide();
            if ($('#covgLIFiveYrSelf').length !== 0 && $('#covgLIFiveYrSps').length !== 0) {
                 if (app.model.data.EligibilityScreen.rdEligIsFullTimeWorkerRequired && app.model.data.EligibilityScreen.rdEligIsFullTimeWorkerRequired == 'Yes') {
                     if (parseInt(params.view.fields.covgLIFiveYrSelf.editor.nestedForm.fields.selBenefitAmt.editor.getValue()) == 100000) {
                         $('.spouse-applying-life').hide();
                         $('#covgLIFiveYrSps_chkAddInsuranceCov').prop('checked', false);
                     } else if ($("#covgLIFiveYrSelf_chkAddInsuranceCov").is(":checked") && parseInt(params.view.fields.covgLIFiveYrSelf.editor.nestedForm.fields.selBenefitAmt.editor.getValue()) == 250000) {
                         if($("#covgLIFiveYrSps_chkAddInsuranceCov").is(":checked")){
                             $('#covgLIFiveYrSps_chkAddInsuranceCov').prop('checked', true);
                         } else {
                             $('#covgLIFiveYrSps_chkAddInsuranceCov').prop('checked', false);
                         }
                         $('.spouse-applying-life').show();
                     }
                 }
                
                this.listenTo(params.view.fields.covgLIFiveYrSelf.editor.nestedForm.fields.selBenefitAmt.editor, 'change', function (event) {
                    if (app.model.data.EligibilityScreen.rdEligIsFullTimeWorkerRequired && app.model.data.EligibilityScreen.rdEligIsFullTimeWorkerRequired == 'Yes') {
                        if (parseInt(event.getValue()) == 100000) {
                            $('.spouse-applying-life').hide();
                            $('#covgLIFiveYrSps_chkAddInsuranceCov').prop('checked', false);
                        } else if ($("#covgLIFiveYrSelf_chkAddInsuranceCov").is(":checked") && parseInt(event.getValue()) == 250000) {
                            $('.spouse-applying-life').show();
                        }
                    }
                });
                this.listenTo(params.view.fields.covgLIFiveYrSelf.editor.nestedForm.fields.chkAddInsuranceCov.editor, 'change', function (event) {
                    if (app.model.data.EligibilityScreen.rdEligIsFullTimeWorkerRequired && app.model.data.EligibilityScreen.rdEligIsFullTimeWorkerRequired == 'Yes') {
                        if (event.getValue() == true && parseInt($("#covgLIFiveYrSelf_selBenefitAmt").val()) == 250000) {
                            $('.spouse-applying-life').show();
                        } else if (event.getValue() == false) {
                            $('.spouse-applying-life').hide();
                            $('#covgLIFiveYrSps_chkAddInsuranceCov').prop('checked', false)
                        }
                    }
                });
            }
        }

